function toPaddedHex(value, width) {
  return value.toString(16).padStart(width, '0');
}

export function formatPythonString(value) {
  let output = "'";

  for (const char of value) {
    const codePoint = char.codePointAt(0);

    if (char === '\\') {
      output += '\\\\';
    } else if (char === '\'') {
      output += '\\\'';
    } else if (char === '\n') {
      output += '\\n';
    } else if (char === '\r') {
      output += '\\r';
    } else if (char === '\t') {
      output += '\\t';
    } else if (codePoint >= 0x20 && codePoint <= 0x7e) {
      output += char;
    } else if (codePoint <= 0xff) {
      output += `\\x${toPaddedHex(codePoint, 2)}`;
    } else if (codePoint <= 0xffff) {
      output += `\\u${toPaddedHex(codePoint, 4)}`;
    } else {
      output += `\\U${toPaddedHex(codePoint, 8)}`;
    }
  }

  output += "'";
  return output;
}

export function formatPythonValue(value) {
  if (typeof value === 'string') {
    return formatPythonString(value);
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : 'nan';
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
  }

  return formatPythonDict(value);
}

export function formatPythonDict(value) {
  const entries = Object.entries(value).map(
    ([key, entryValue]) => `${formatPythonString(key)}: ${formatPythonValue(entryValue)}`,
  );
  return `{${entries.join(', ')}}`;
}

import { OPTION_SPECS, buildHelpText, buildUsage } from './spec.mjs';

function buildResult(exitCode, stream, output) {
  return {
    ok: false,
    exitCode,
    stream,
    output,
  };
}

function buildError(programName, message) {
  return buildResult(
    2,
    'stderr',
    `${buildUsage(programName)}${programName}: error: ${message}\n`,
  );
}

function buildHelp(programName) {
  return buildResult(0, 'stdout', buildHelpText(programName));
}

function looksLikeOptionalToken(token) {
  return token !== '-' && token.startsWith('-');
}

function resolveLongOption(name) {
  for (const option of OPTION_SPECS) {
    if (option.long === name) {
      return option;
    }
  }

  const matches = OPTION_SPECS.filter((option) => option.long.startsWith(name));
  if (matches.length === 1) {
    return matches[0];
  }

  if (matches.length > 1) {
    return {
      ambiguous: true,
      matches,
    };
  }

  return null;
}

function validateChoice(option, value, programName) {
  if (!option.choices || option.choices.includes(value)) {
    return null;
  }

  const formattedChoices = option.choices.map((choice) => `'${choice}'`).join(', ');
  return buildError(
    programName,
    `argument ${option.long}: invalid choice: '${value}' (choose from ${formattedChoices})`,
  );
}

export function parseCommandLine(argv, programName) {
  let data;
  let verifyIat;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token === '-h') {
      return buildHelp(programName);
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const inlineValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const option = resolveLongOption(optionName);

      if (option === null) {
        extras.push(token);
        continue;
      }

      if (option.ambiguous) {
        const matches = option.matches.map((match) => match.long).join(', ');
        return buildError(programName, `ambiguous option: ${optionName} could match ${matches}`);
      }

      if (!option.takesValue) {
        return buildHelp(programName);
      }

      let value = inlineValue;
      if (value === null) {
        const next = argv[index + 1];
        if (next === undefined || looksLikeOptionalToken(next)) {
          return buildError(programName, `argument ${option.long}: expected one argument`);
        }

        value = next;
        index += 1;
      }

      const choiceError = validateChoice(option, value, programName);
      if (choiceError) {
        return choiceError;
      }

      if (option.key === 'data') {
        data = value;
      } else if (option.key === 'verify_iat') {
        verifyIat = value;
      }

      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (data === undefined) {
    missing.push('--data');
  }

  if (verifyIat === undefined) {
    missing.push('--verify_iat');
  }

  if (missing.length > 0) {
    return buildError(
      programName,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    return buildError(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    ok: true,
    args: {
      data,
      verify_iat: verifyIat,
    },
  };
}

